// 1. The Blueprint
class Student {
    String name;
    int age;
    String course;
    double marks;

    void displayProfile() {
        System.out.println("--- Student Profile ---");
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Course: " + course);
        System.out.println("Marks: " + marks);
        System.out.println(); // Blank line for clean spacing
    }
}

// 2. The Execution Driver
public class Main {
    public static void main(String[] args) {
        // Student 1
        Student student1 = new Student();
        student1.name = "Rahul";
        student1.age = 20;
        student1.course = "Java";
        student1.marks = 85.5;

        // Student 2
        Student student2 = new Student();
        student2.name = "Priya";
        student2.age = 21;
        student2.course = "Python";
        student2.marks = 91.0;

        // Display both profiles
        student1.displayProfile();
        student2.displayProfile();
    }
}

