class Student {
    String name;
    int age;
    String course;
    double marks;

    void displayProfile() {
        System.out.println("--- Student Profile ---");
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Course: " + course);
        System.out.println("Marks: " + marks);
    }
}

public class Main {
    public static void main(String[] args) {
        Student s1 = new Student();
        s1.name = "Rahul";
        s1.age = 20;
        s1.course = "Java";
        s1.marks = 85.5;

        Student s2 = new Student();
        s2.name = "Priya";
        s2.age = 21;
        s2.course = "Python";
        s2.marks = 91.0;

        s1.displayProfile();
        System.out.println();
        s2.displayProfile();
    }
}

class Student {
    String name;
    int age;
    String course;
    double marks;
    String city;

    void displayProfile() {
        System.out.println("--- Student Profile ---");
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Course: " + course);
        System.out.println("Marks: " + marks);
        System.out.println("City: " + city);
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student();
        s.name = "Arjun";
        s.age = 19;
        s.course = "Java";
        s.marks = 78.0;
        s.city = "Mumbai";
        s.displayProfile();
    }
}
